const require_index = require("../useFirstMountState/index.js");
//#region src/createUpdateEffect/index.ts
const createUpdateEffect = (hook) => (effect, deps) => {
	const isFirstMount = require_index.useFirstMountState();
	hook(() => {
		if (!isFirstMount) return effect();
	}, deps);
};
//#endregion
exports.default = createUpdateEffect;
